static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int month = monthDay / 100;
        int day = monthDay % 100;

        // Calculate the day of the year
        int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29;
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        // Calculate the new day of the year based on dayStep
        int newDayOfYear = (dayOfYear / dayStep) * dayStep + 1;

        // Convert the new day of the year back to month and day
        int newMonth = 1;
        int newDay = newDayOfYear;
        while (newDay > daysInMonth[newMonth - 1]) {
            newDay -= daysInMonth[newMonth - 1];
            newMonth++;
        }

        // Return the new time bucket
        return year * 10000 + newMonth * 100 + newDay;
    } catch (Exception e) {
        // Handle invalid input gracefully
        return -1;
    }
}

