    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        int adjustedDay = day - (day % dayStep) + 1;

        return year * 10000 + month * 100 + Math.min(adjustedDay, getDaysInMonth(year, month));
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid timeBucket format", e);
    }
}

private static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }
}

private static boolean isLeapYear(int year) {
    if (year % 4 != 0) {
        return false;
    } else if (year % 100 != 0) {
        return true;
    } else {
        return year % 400 == 0;
    }
}

