public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int length = str.length();
    int size = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length) {
                char d = str.charAt(i + 1);
                if (Character.isSurrogatePair(c, d)) {
                    size += 4;
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair in string");
                }
            } else {
                throw new IllegalArgumentException("Truncated surrogate pair in string");
            }
        } else {
            size += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = lb.offset;

    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer = ensureCapacity(buffer, 1);
            buffer.buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            buffer = ensureCapacity(buffer, 2);
            buffer.buffer[offset++] = (byte) (0xc0 | (c >> 6));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < length) {
                char d = str.charAt(i + 1);
                if (Character.isSurrogatePair(c, d)) {
                    int codePoint = Character.toCodePoint(c, d);
                    buffer = ensureCapacity(buffer, 4);
                    buffer.buffer[offset++] = (byte) (0xf0 | (codePoint >> 18));
                    buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                    buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                    buffer.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3f));
                    i++;
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair in string");
                }
            } else {
                throw new IllegalArgumentException("Truncated surrogate pair in string");
            }
        } else {
            buffer = ensureCapacity(buffer, 3);
            buffer.buffer[offset++] = (byte) (0xe0 | (c >> 12));
            buffer.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        }
    }

    buffer.offset = offset;
    return buffer;
}

private static LinkedBuffer ensureCapacity(final LinkedBuffer buffer, final int capacity) {
    if (buffer.buffer.length - buffer.offset < capacity) {
        int newSize = buffer.buffer.length << 1;
        if (newSize - buffer.offset < capacity) {
            newSize = buffer.offset + capacity;
        }
        LinkedBuffer newBuffer = new LinkedBuffer(newSize);
        System.arraycopy(buffer.buffer, 0, newBuffer.buffer, 0, buffer.offset);
        newBuffer.offset = buffer.offset;
        newBuffer.next = buffer.next;
        buffer.next = newBuffer;
        return newBuffer;
    }
    return buffer;
}

