        if (c >= 0x0001 && c <= 0x007F) {
            utflen++;
        } else if (c > 0x07FF) {
            utflen += 3;
        } else {
            utflen += 2;
        }
    }

    if (utflen > lb.remaining()) {
        throw new BufferOverflowException();
    }

    byte[] bytes = new byte[utflen];
