private static String substituteVariables(String value, Properties props) {
    if (value == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int varStart = -1;
    for (int i = 0; i < value.length(); i++) {
        char c = value.charAt(i);
        if (c == '$' && i + 1 < value.length() && value.charAt(i + 1) == '{') {
            if (varStart == -1) {
                varStart = i;
            }
        } else if (c == '}' && varStart != -1) {
            String varName = value.substring(varStart + 2, i);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append("${").append(varName).append("}");
            }
            varStart = -1;
        } else if (varStart == -1) {
            result.append(c);
        }
    }
    if (varStart != -1) {
        result.append(value.substring(varStart));
    }
    return result.toString();
}

