String substVars(String val, Properties props) throws Exception {
    StringBuffer sbuf = new StringBuffer();
    int i = 0;
    while (i < val.length()) {
        char c = val.charAt(i);
        if (c == '$') {
            if (i == val.length() - 1) {
                throw new IllegalArgumentException("Invalid variable substitution: $ at the end of string");
            }
            if (val.charAt(i + 1) == '{') {
                int end = val.indexOf('}', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid variable substitution: missing }");
                }
                String var = val.substring(i + 2, end);
                String v = props.getProperty(var);
                if (v != null) {
                    sbuf.append(v);
                }
                i = end + 1;
            } else {
                sbuf.append(c);
                i++;
            }
        } else {
            sbuf.append(c);
            i++;
        }
    }
    return sbuf.toString();
}

