private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int startIndex = 0;
    int endIndex = value.indexOf("${");
    while (endIndex != -1) {
        result.append(value, startIndex, endIndex);
        startIndex = endIndex + 2;
        endIndex = value.indexOf('}', startIndex);
        if (endIndex == -1) {
            break;
        }
        String varName = value.substring(startIndex, endIndex);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append("${").append(varName).append("}");
        }
        startIndex = endIndex + 1;
        endIndex = value.indexOf("${", startIndex);
    }
    result.append(value.substring(startIndex));
    return result.toString();
}

