        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        boolean isAbsolute = path.startsWith("/");
        String[] segments = path.split("/");

        int startIndex = isAbsolute ? 1 : 0;
        for (int i = startIndex; i < segments.length; i++) {
            String segment = segments[i];
            if (decode) {
                segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    } catch (UnsupportedEncodingException e) {
        // UTF-8 is always supported, so this exception should never be thrown
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
}

