        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
        case 'F': // float
        case 'J': // long
        case 'D': // double
        case 'L': // reference type
        case '[': // array type
            // Pop a single item from the stack
            // Assuming there's a method pop() that pops a single item
            pop();
            break;
        case '(':
            // Method descriptor, parse arguments and pop them
            int i = 1;
            while (descriptor.charAt(i) != ')') {
                i += popType(descriptor, i);
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'V': // void is not a valid argument type
            throw new IllegalArgumentException("Void is not a valid argument type in descriptor: " + descriptor);
        case 'Z': // boolean
        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
        case 'F': // float
            // Pop a single item from the stack
            pop();
            return 1;
        case 'J': // long
        case 'D': // double
            // Pop two items from the stack
            pop();
            pop();
            return 1;
        case 'L':
            // Reference type, skip to the end of the descriptor for this type
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            pop();
            return index + 1;
        case '[':
            // Array type, skip to the end of the descriptor for this type
            int skip = 0;
            while (descriptor.charAt(index + skip) == '[') {
                skip++;
            }
            if (descriptor.charAt(index + skip) == 'L') {
                while (descriptor.charAt(index + skip) != ';') {
                    skip++;
                }
            }
            pop();
            return skip + 1;
        default:
            throw new IllegalArgumentException("Invalid type descriptor at index " + index + ": " + descriptor);
    }
}

void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    int length = descriptor.length();
    int i = 0;

    while (i < length) {
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'D': case 'F': case 'I':
            case 'J': case 'S': case 'V': case 'Z':
                // These types take up one stack slot, pop one from stack.
                // Do nothing here, just move to the next character.
                break;
            case 'L':
                // Object type, pop one from stack.
                // Find the next semicolon to skip the class name.
                while (i < length && descriptor.charAt(i) != ';') {
                    i++;
                }
                break;
            case '[':
                // Array type, pop one from stack.
                // Do nothing special, just move to the next character to parse the element type.
                break;
            case '(':
                // Method descriptor starts, parse each argument descriptor.
                i++; // Move past '('
                while (i < length && descriptor.charAt(i) != ')') {
                    pop(descriptor.substring(i, i + 1)); // Recursively pop each argument type.
                    // Move i to the position right after the current argument type descriptor.
                    switch (descriptor.charAt(i)) {
                        case 'B': case 'C': case 'D': case 'F': case 'I':
                        case 'J': case 'S': case 'V': case 'Z':
                            i++;
                            break;
                        case 'L':
                            // Find the next semicolon to skip the class name.
                            while (i < length && descriptor.charAt(i) != ';') {
                                i++;
                            }
                            i++; // Move past ';'
                            break;
                        case '[':
                            // Skip all '[' characters.
                            while (i < length && descriptor.charAt(i) == '[') {
                                i++;
                            }
                            // The next character should be a type descriptor.
                            if (i < length) {
                                i++;
                            }
                            break;
                        default:
                            throw new IllegalArgumentException("Invalid descriptor at position " + i);
                    }
                }
                i++; // Move past ')'
                // Now parse the return type.
                if (i < length) {
                    pop(descriptor.substring(i));
                }
                return; // Return after processing method descriptor.
            default:
                throw new IllegalArgumentException("Invalid descriptor at position " + i);
        }
        i++;
    }
}

