public final byte[] toByteArray(){
    if (isRead) {
        byte[] result = new byte[(int) getSize()];
        int position = 0;
        for (ByteBuffer buffer : buffers) {
            int remaining = buffer.remaining();
            buffer.get(result, position, remaining);
            position += remaining;
        }
        return result;
    } else {
        throw new IllegalStateException("Content has not been read yet.");
    }
}

public final byte[] toByteArray() {
    if (isRead) {
        byte[] result = new byte[(int) getSize()];
        int offset = 0;
        for (ByteBuffer buffer : buffers) {
            int length = buffer.position();
            buffer.rewind();
            buffer.get(result, offset, length);
            offset += length;
            buffer.position(length); // Reset position to original
        }
        return result;
    } else {
        throw new IllegalStateException("Buffer has not been read yet.");
    }
}

public final byte[] toByteArray(){
    try {
        if (buffers == null || buffers.isEmpty()) {
            return new byte[0];
        }
        int totalLength = 0;
        for (ByteBuffer buffer : buffers) {
            totalLength += buffer.position();
        }
        byte[] result = new byte[totalLength];
        int offset = 0;
        for (ByteBuffer buffer : buffers) {
            buffer.flip();
            buffer.get(result, offset, buffer.position());
            offset += buffer.position();
        }
        return result;
    } catch (Exception e) {
        e.printStackTrace();
        return new byte[0];
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            output.append(c);
        } else {
            if (i + 1 >= str.length()) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(++i);
            switch (next) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '\"':
                    output.append('\"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    if (next == 'u') {
                        if (i + 4 >= str.length()) {
                            throw new Exception("Invalid Unicode escape sequence");
                        }
                        String hex = str.substring(i + 1, i + 5);
                        output.append((char) Integer.parseInt(hex, 16));
                        i += 4;
                    } else {
                        throw new Exception("Invalid escape sequence: \\" + next);
                    }
                    break;
            }
        }
    }
    return output.toString();
}

