protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }

    int removedCount = 0;
    Queue<CategoryNode> queue = new LinkedList<>();
    queue.add(root);

    while (!queue.isEmpty()) {
        CategoryNode node = queue.poll();

        if (node.isActive()) {
            for (CategoryNode child : node.getChildren()) {
                queue.add(child);
            }
        } else {
            node.getParent().removeChild(node);
            removedCount++;
        }
    }

    return removedCount;
}

