protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return null; // or throw an exception based on requirements
    }
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (!vertexList.get(vertexList.size() - 1).equals(source)) {
            throw new IllegalArgumentException("Edges do not form a valid path");
        }
        vertexList.add(target);
    }
    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return null; // or consider returning an empty graph path if applicable
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V currentVertex = null;

    // Find a starting vertex
    for (E edge : edgeList) {
        startVertex = graph.getEdgeSource(edge);
        currentVertex = graph.getEdgeTarget(edge);
        if (graph.containsVertex(startVertex)) {
            break;
        }
    }

    if (startVertex == null || currentVertex == null) {
        throw new IllegalArgumentException("Tour edges do not form a valid path in the graph");
    }

    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    Set<E> usedEdges = new HashSet<>();

    while (!usedEdges.containsAll(edgeList)) {
        for (E edge : edgeList) {
            if (!usedEdges.contains(edge)) {
                V source = graph.getEdgeSource(edge);
                V target = graph.getEdgeTarget(edge);
                if (source.equals(currentVertex)) {
                    currentVertex = target;
                    usedEdges.add(edge);
                    vertexList.add(currentVertex);
                    break;
                } else if (target.equals(currentVertex)) {
                    currentVertex = source;
                    usedEdges.add(edge);
                    vertexList.add(currentVertex);
                    break;
                }
            }
        }
    }

    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();
    List<E> edgeList = new ArrayList<>(tour);

    if (edgeList.isEmpty()) {
        return path; // Return an empty path if the tour is empty
    }

    // Assuming the graph is connected and Eulerian, find a starting vertex
    V startVertex = null;
    for (E edge : edgeList) {
        startVertex = graph.getEdgeSource(edge);
        break;
    }

    if (startVertex == null) {
        throw new IllegalStateException("Graph does not contain any edges");
    }

    path.setStartVertex(startVertex);
    V currentVertex = startVertex;

    for (E edge : edgeList) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains an edge not present in the graph");
        }
        path.addEdge(edge);
        currentVertex = graph.getEdgeTarget(edge);
    }

    path.setEndVertex(currentVertex);

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Neither tour nor graph can be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new SimpleGraphPath<>(graph, new ArrayList<>());
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertexList.add(targetVertex);
    }

    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();

    if (edgeList.isEmpty()) {
        return path; // Return an empty path if the tour is empty
    }

    // Assuming the graph is connected and the tour is a valid cycle
    V startVertex = null;
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = source;
        }
        path.addEdge(edge);
        path.addVertex(target);
    }

    // Add the start vertex to close the loop if it's not already there
    if (!path.getStartVertex().equals(path.getEndVertex())) {
        path.addVertex(startVertex);
    }

    return path;
}

