private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++; // skip the backslash
            if (i < input.length()) {
                c = input.charAt(i);
                // handle escaped characters
                switch (c) {
                    case 'u': // Unicode escape
                        if (i + 4 < input.length()) {
                            String unicodeStr = input.substring(i + 1, i + 5);
                            try {
                                int unicode = Integer.parseInt(unicodeStr, 16);
                                output.append((char) unicode);
                                i += 4; // skip the unicode digits
                            } catch (NumberFormatException e) {
                                // Invalid unicode, just append the characters
                                output.append("\\u").append(unicodeStr);
                            }
                        } else {
                            // Invalid escape, append as is
                            output.append('\\').append('u');
                        }
                        break;
                    default:
                        // Other escapes, just append the next character
                        output.append(c);
                }
            } else {
                // Trailing backslash, just append it
                output.append('\\');
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

