private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
            // These are single-slot types
            index++;
            break;
        case 'D':
        case 'J':
            // These are double-slot types
            index += 2;
            break;
        case 'L':
            // Object type
            index = descriptor.indexOf(';', index) + 1;
            break;
        case '[':
            // Array type, skip to the end of the array descriptor
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            index = popType(descriptor, index); // Recursively pop the array's component type
            break;
        default:
            throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(index));
    }
    return index;
}

