public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must not be null");
    }

    // Normalize the paths
    path = path.replaceAll("\\\\", "/");
    relativePath = relativePath.replaceAll("\\\\", "/");

    // Handle the case where the relative path is empty or "."
    if (relativePath.isEmpty() || relativePath.equals(".")) {
        return path;
    }

    // Handle the case where the relative path is ".." or starts with "../"
    if (relativePath.equals("..")) {
        return path.substring(0, path.lastIndexOf('/'));
    } else if (relativePath.startsWith("../")) {
        int levelsUp = relativePath.split("\\.\\./").length - 1;
        String result = path;
        for (int i = 0; i < levelsUp; i++) {
            result = result.substring(0, result.lastIndexOf('/'));
        }
        relativePath = relativePath.substring(levelsUp * 3);
        if (relativePath.isEmpty()) {
            return result;
        }
    }

    // Trim trailing slash from path if present
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Append the relative path to the path
    return path + "/" + relativePath;
}

