    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to build the final path components
    List<String> resultPathComponents = new ArrayList<>(Arrays.asList(pathComponents));

    // Apply the relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!resultPathComponents.isEmpty()) {
                resultPathComponents.remove(resultPathComponents.size() - 1);
            }
        } else if (!component.equals(".")) {
            resultPathComponents.add(component);
        }
    }

    // Join the components back into a single string
    return String.join("/", resultPathComponents);
}

