        }

        // Normalize the paths
        String normalizedPath = path.endsWith("/") ? path : path + "/";
        String normalizedRelativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

        // Split the paths into components
        String[] pathComponents = normalizedPath.split("/");
        String[] relativePathComponents = normalizedRelativePath.split("/");

        // Process the relative path components
        for (String component : relativePathComponents) {
            if (component.equals("..")) {
                if (pathComponents.length > 1) { // Avoid removing the root
                    pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
                }
            } else if (!component.equals(".")) { // Skip current directory component
                List<String> pathList = new ArrayList<>(Arrays.asList(pathComponents));
                pathList.add(component);
                pathComponents = pathList.toArray(new String[0]);
            }
        }

        // Join the components back into a single path
        return String.join("/", pathComponents);
    } catch (Exception e) {
        throw new RuntimeException("Error applying relative path", e);
    }
}

